#include <format>
#include <iostream>
#include <string_view>
#include <utility>
#include <vector>

enum class MissionState { idle, running, cancelling, finished, failed };

[[nodiscard]] constexpr std::string_view name_of(MissionState state) {
  switch (state) {
    case MissionState::idle:
      return "idle";
    case MissionState::running:
      return "running";
    case MissionState::cancelling:
      return "cancelling";
    case MissionState::finished:
      return "finished";
    case MissionState::failed:
      return "failed";
  }
  return "unknown";
}

// The five edges a mission may follow. Anything else is refused.
[[nodiscard]] constexpr bool valid_transition(MissionState from, MissionState to) {
  switch (from) {
    case MissionState::idle:
      return to == MissionState::running;
    case MissionState::running:
      return to == MissionState::cancelling || to == MissionState::finished || to == MissionState::failed;
    case MissionState::cancelling:
      return to == MissionState::finished;
    case MissionState::finished:
    case MissionState::failed:
      return false;
  }
  return false;
}

int main() {
  const std::vector<std::pair<MissionState, MissionState>> tries{
      {MissionState::idle, MissionState::running},
      {MissionState::running, MissionState::cancelling},
      {MissionState::cancelling, MissionState::finished},
      {MissionState::running, MissionState::failed},
      {MissionState::running, MissionState::idle},
      {MissionState::finished, MissionState::running},
  };
  for (const auto& [from, to] : tries) {
    std::cout << std::format("{:<11} -> {:<11} {}\n", name_of(from), name_of(to), valid_transition(from, to));
  }
}

