#include <format>
#include <iostream>
#include <memory>
#include <string_view>
#include <utility>

// One class per state. Each overrides only the events it reacts to; the rest are ignored by default.
class ConnectionState {
 public:
  ConnectionState() = default;
  ConnectionState(const ConnectionState&) = delete;
  ConnectionState& operator=(const ConnectionState&) = delete;
  virtual ~ConnectionState() = default;
  [[nodiscard]] virtual std::string_view name() const = 0;
  [[nodiscard]] virtual std::unique_ptr<ConnectionState> on_connect() { return nullptr; }
  [[nodiscard]] virtual std::unique_ptr<ConnectionState> on_open_ack() { return nullptr; }
  [[nodiscard]] virtual std::unique_ptr<ConnectionState> on_timeout() { return nullptr; }
  [[nodiscard]] virtual std::unique_ptr<ConnectionState> on_close() { return nullptr; }
};

class Connecting;
class Connected;

class Disconnected final : public ConnectionState {
 public:
  [[nodiscard]] std::string_view name() const override { return "disconnected"; }
  [[nodiscard]] std::unique_ptr<ConnectionState> on_connect() override;
};

class Connecting final : public ConnectionState {
 public:
  [[nodiscard]] std::string_view name() const override { return "connecting"; }
  [[nodiscard]] std::unique_ptr<ConnectionState> on_open_ack() override;
  [[nodiscard]] std::unique_ptr<ConnectionState> on_timeout() override;
};

class Connected final : public ConnectionState {
 public:
  [[nodiscard]] std::string_view name() const override { return "connected"; }
  [[nodiscard]] std::unique_ptr<ConnectionState> on_close() override;
};

std::unique_ptr<ConnectionState> Disconnected::on_connect() { return std::make_unique<Connecting>(); }
std::unique_ptr<ConnectionState> Connecting::on_open_ack() { return std::make_unique<Connected>(); }
std::unique_ptr<ConnectionState> Connecting::on_timeout() { return std::make_unique<Disconnected>(); }
std::unique_ptr<ConnectionState> Connected::on_close() { return std::make_unique<Disconnected>(); }

class Connection {
 public:
  Connection() : state_(std::make_unique<Disconnected>()) {}

  void connect() { transition(state_->on_connect()); }
  void open_ack() { transition(state_->on_open_ack()); }
  void timeout() { transition(state_->on_timeout()); }
  void close() { transition(state_->on_close()); }

  [[nodiscard]] std::string_view state() const { return state_->name(); }

 private:
  void transition(std::unique_ptr<ConnectionState> next) {
    if (next) state_ = std::move(next);
  }

  std::unique_ptr<ConnectionState> state_;
};

int main() {
  Connection link;
  std::cout << std::format("start:              {}\n", link.state());
  link.connect();
  std::cout << std::format("after connect():    {}\n", link.state());
  link.close();  // Connecting has no on_close override: ignored, the state stays
  std::cout << std::format("close() while connecting, ignored: {}\n", link.state());
  link.open_ack();
  std::cout << std::format("after open_ack():   {}\n", link.state());
  link.close();
  std::cout << std::format("after close():      {}\n", link.state());
}

#include <format>
#include <iostream>
#include <string_view>
#include <type_traits>
#include <variant>

enum class Event { connect, open_ack, timeout, close };
enum class SimpleState { disconnected, connecting, connected };

[[nodiscard]] constexpr std::string_view name_of(SimpleState state) {
  switch (state) {
    case SimpleState::disconnected:
      return "disconnected";
    case SimpleState::connecting:
      return "connecting";
    case SimpleState::connected:
      return "connected";
  }
  return "unknown";
}

// One function, one switch: the whole machine in one place.
[[nodiscard]] constexpr SimpleState next(SimpleState state, Event event) {
  switch (state) {
    case SimpleState::disconnected:
      return event == Event::connect ? SimpleState::connecting : state;
    case SimpleState::connecting:
      if (event == Event::open_ack) return SimpleState::connected;
      if (event == Event::timeout) return SimpleState::disconnected;
      return state;
    case SimpleState::connected:
      return event == Event::close ? SimpleState::disconnected : state;
  }
  return state;
}

// The same three states as tag structs in a variant, visited with one function.
struct Disconnected {};
struct Connecting {};
struct Connected {};
using AnyState = std::variant<Disconnected, Connecting, Connected>;

[[nodiscard]] std::string_view name_of(const AnyState& state) {
  return std::visit(
      [](const auto& s) -> std::string_view {
        using T = std::decay_t<decltype(s)>;
        if constexpr (std::is_same_v<T, Disconnected>) return "disconnected";
        if constexpr (std::is_same_v<T, Connecting>) return "connecting";
        return "connected";
      },
      state);
}

[[nodiscard]] AnyState next(const AnyState& state, Event event) {
  return std::visit(
      [event](const auto& s) -> AnyState {
        using T = std::decay_t<decltype(s)>;
        if constexpr (std::is_same_v<T, Disconnected>) {
          return event == Event::connect ? AnyState{Connecting{}} : AnyState{s};
        } else if constexpr (std::is_same_v<T, Connecting>) {
          if (event == Event::open_ack) return AnyState{Connected{}};
          if (event == Event::timeout) return AnyState{Disconnected{}};
          return AnyState{s};
        } else {
          return event == Event::close ? AnyState{Disconnected{}} : AnyState{s};
        }
      },
      state);
}

int main() {
  SimpleState enum_state = SimpleState::disconnected;
  AnyState variant_state = Disconnected{};
  for (const Event event : {Event::connect, Event::close, Event::open_ack, Event::close}) {
    enum_state = next(enum_state, event);
    variant_state = next(variant_state, event);
    std::cout << std::format("enum: {:<13} variant: {:<13} agree: {}\n", name_of(enum_state), name_of(variant_state),
                             name_of(enum_state) == name_of(variant_state));
  }
  std::cout << std::format("sizeof SimpleState: {}, sizeof AnyState: {}\n", sizeof(SimpleState), sizeof(AnyState));
}

#include <format>
#include <iostream>
#include <memory>
#include <string_view>
#include <type_traits>
#include <utility>
#include <variant>
#include <vector>

enum class MissionEvent { start, cancel, complete, fail };

[[nodiscard]] constexpr std::string_view name_of(MissionEvent event) {
  switch (event) {
    case MissionEvent::start:
      return "start";
    case MissionEvent::cancel:
      return "cancel";
    case MissionEvent::complete:
      return "complete";
    case MissionEvent::fail:
      return "fail";
  }
  return "unknown";
}

// ---- 1. One class per state ----

class MissionState {
 public:
  MissionState() = default;
  MissionState(const MissionState&) = delete;
  MissionState& operator=(const MissionState&) = delete;
  virtual ~MissionState() = default;
  [[nodiscard]] virtual std::string_view name() const = 0;
  // Ignored by default: a state that overrides nothing rejects every event.
  [[nodiscard]] virtual std::unique_ptr<MissionState> on_event(MissionEvent) const { return nullptr; }
};

class Running;
class Cancelling;

class Idle final : public MissionState {
 public:
  [[nodiscard]] std::string_view name() const override { return "idle"; }
  [[nodiscard]] std::unique_ptr<MissionState> on_event(MissionEvent event) const override;
};

class Running final : public MissionState {
 public:
  [[nodiscard]] std::string_view name() const override { return "running"; }
  [[nodiscard]] std::unique_ptr<MissionState> on_event(MissionEvent event) const override;
};

class Cancelling final : public MissionState {
 public:
  [[nodiscard]] std::string_view name() const override { return "cancelling"; }
  [[nodiscard]] std::unique_ptr<MissionState> on_event(MissionEvent event) const override;
};

class Finished final : public MissionState {
 public:
  [[nodiscard]] std::string_view name() const override { return "finished"; }
};

class Failed final : public MissionState {
 public:
  [[nodiscard]] std::string_view name() const override { return "failed"; }
};

std::unique_ptr<MissionState> Idle::on_event(MissionEvent event) const {
  if (event == MissionEvent::start) return std::make_unique<Running>();
  return nullptr;
}
std::unique_ptr<MissionState> Running::on_event(MissionEvent event) const {
  if (event == MissionEvent::cancel) return std::make_unique<Cancelling>();
  if (event == MissionEvent::complete) return std::make_unique<Finished>();
  if (event == MissionEvent::fail) return std::make_unique<Failed>();
  return nullptr;
}
std::unique_ptr<MissionState> Cancelling::on_event(MissionEvent event) const {
  if (event == MissionEvent::complete) return std::make_unique<Finished>();
  return nullptr;
}

class Mission {
 public:
  Mission() : state_(std::make_unique<Idle>()) {}

  [[nodiscard]] bool handle(MissionEvent event) {
    std::unique_ptr<MissionState> next = state_->on_event(event);
    if (!next) return false;
    state_ = std::move(next);
    return true;
  }
  [[nodiscard]] std::string_view state() const { return state_->name(); }

 private:
  std::unique_ptr<MissionState> state_;
};

// ---- 2. The same five states as tag structs in a variant ----

struct IdleV {};
struct RunningV {};
struct CancellingV {};
struct FinishedV {};
struct FailedV {};
using AnyMissionState = std::variant<IdleV, RunningV, CancellingV, FinishedV, FailedV>;

[[nodiscard]] std::string_view name_of(const AnyMissionState& state) {
  return std::visit(
      [](const auto& s) -> std::string_view {
        using T = std::decay_t<decltype(s)>;
        if constexpr (std::is_same_v<T, IdleV>) return "idle";
        else if constexpr (std::is_same_v<T, RunningV>) return "running";
        else if constexpr (std::is_same_v<T, CancellingV>) return "cancelling";
        else if constexpr (std::is_same_v<T, FinishedV>) return "finished";
        else return "failed";
      },
      state);
}

// Returns whether the event was accepted; on rejection, state is left unchanged.
[[nodiscard]] bool handle(AnyMissionState& state, MissionEvent event) {
  return std::visit(
      [&state, event](const auto& s) -> bool {
        using T = std::decay_t<decltype(s)>;
        if constexpr (std::is_same_v<T, IdleV>) {
          if (event == MissionEvent::start) {
            state = RunningV{};
            return true;
          }
        } else if constexpr (std::is_same_v<T, RunningV>) {
          if (event == MissionEvent::cancel) {
            state = CancellingV{};
            return true;
          }
          if (event == MissionEvent::complete) {
            state = FinishedV{};
            return true;
          }
          if (event == MissionEvent::fail) {
            state = FailedV{};
            return true;
          }
        } else if constexpr (std::is_same_v<T, CancellingV>) {
          if (event == MissionEvent::complete) {
            state = FinishedV{};
            return true;
          }
        }
        return false;
      },
      state);
}

int main() {
  Mission classes;
  AnyMissionState variant = IdleV{};

  const std::vector<MissionEvent> events{MissionEvent::start, MissionEvent::cancel, MissionEvent::complete,
                                         MissionEvent::start, MissionEvent::fail};
  for (const MissionEvent event : events) {
    const bool accepted_by_class = classes.handle(event);
    const bool accepted_by_variant = handle(variant, event);
    std::cout << std::format("{:<9} accepted {:<5} -> {:<10} (variant accepted {:<5} -> {:<10}) agree: {}\n",
                             name_of(event), accepted_by_class, classes.state(), accepted_by_variant,
                             name_of(variant), classes.state() == name_of(variant));
  }
}

#include <format>
#include <iostream>
#include <string_view>

enum class MissionState { idle, running, cancelling, finished, failed };
enum class MissionEvent { start, cancel, complete, fail };

[[nodiscard]] constexpr std::string_view name_of(MissionState state) {
  switch (state) {
    case MissionState::idle:
      return "idle";
    case MissionState::running:
      return "running";
    case MissionState::cancelling:
      return "cancelling";
    case MissionState::finished:
      return "finished";
    case MissionState::failed:
      return "failed";
  }
  return "unknown";
}

// The bug: switches on the event alone, and never looks at the state it started in.
[[nodiscard]] constexpr MissionState buggy_next(MissionState state, MissionEvent event) {
  switch (event) {
    case MissionEvent::start:
      return MissionState::running;
    case MissionEvent::cancel:
      return MissionState::cancelling;
    case MissionEvent::complete:
      return MissionState::finished;
    case MissionEvent::fail:
      return MissionState::failed;
  }
  return state;
}

int main() {
  MissionState state = MissionState::finished;  // the mission is already over
  std::cout << std::format("before: {}\n", name_of(state));
  state = buggy_next(state, MissionEvent::start);  // a stray start event arrives late
  std::cout << std::format("after a stray start event: {}\n", name_of(state));
}

#include <array>
#include <format>
#include <iostream>
#include <string_view>

enum class MissionState { idle, running, cancelling, finished, failed };
enum class MissionEvent { start, cancel, complete, fail };

[[nodiscard]] constexpr std::string_view name_of(MissionState state) {
  switch (state) {
    case MissionState::idle:
      return "idle";
    case MissionState::running:
      return "running";
    case MissionState::cancelling:
      return "cancelling";
    case MissionState::finished:
      return "finished";
    case MissionState::failed:
      return "failed";
  }
  return "unknown";
}

[[nodiscard]] constexpr std::string_view name_of(MissionEvent event) {
  switch (event) {
    case MissionEvent::start:
      return "start";
    case MissionEvent::cancel:
      return "cancel";
    case MissionEvent::complete:
      return "complete";
    case MissionEvent::fail:
      return "fail";
  }
  return "unknown";
}

[[nodiscard]] constexpr MissionState correct_next(MissionState state, MissionEvent event) {
  switch (state) {
    case MissionState::idle:
      return event == MissionEvent::start ? MissionState::running : state;
    case MissionState::running:
      if (event == MissionEvent::cancel) return MissionState::cancelling;
      if (event == MissionEvent::complete) return MissionState::finished;
      if (event == MissionEvent::fail) return MissionState::failed;
      return state;
    case MissionState::cancelling:
      return event == MissionEvent::complete ? MissionState::finished : state;
    case MissionState::finished:
    case MissionState::failed:
      return state;
  }
  return state;
}

// The bug from the previous fence: switches on the event alone.
[[nodiscard]] constexpr MissionState buggy_next(MissionState state, MissionEvent event) {
  switch (event) {
    case MissionEvent::start:
      return MissionState::running;
    case MissionEvent::cancel:
      return MissionState::cancelling;
    case MissionEvent::complete:
      return MissionState::finished;
    case MissionEvent::fail:
      return MissionState::failed;
  }
  return state;
}

int main() {
  constexpr std::array<MissionState, 5> states{MissionState::idle, MissionState::running, MissionState::cancelling,
                                               MissionState::finished, MissionState::failed};
  constexpr std::array<MissionEvent, 4> events{MissionEvent::start, MissionEvent::cancel, MissionEvent::complete,
                                               MissionEvent::fail};
  int mismatches = 0;
  for (const MissionState state : states) {
    for (const MissionEvent event : events) {
      const MissionState correct = correct_next(state, event);
      const MissionState buggy = buggy_next(state, event);
      if (correct != buggy) {
        ++mismatches;
        std::cout << std::format("mismatch: {:<10} + {:<8} -> correct {:<10} buggy {}\n", name_of(state),
                                 name_of(event), name_of(correct), name_of(buggy));
      }
    }
  }
  std::cout << std::format("checked {} state-event pairs, {} mismatches\n", states.size() * events.size(),
                           mismatches);
}
